void FFmpegVideoDecodeEngine_Initialize(MessageLoop* message_loop, VideoDecodeEngine::EventHandler* event_handler, VideoDecodeContext* context, const VideoDecoderConfig& config) {
    AVCodecContext* codec_ctx = avcodec_alloc_context3(NULL);
    if (!codec_ctx) {
        // Handle error
        return;
    }

    // Setup codec parameters from config
    if (avcodec_open2(codec_ctx, avcodec_find_decoder(AV_CODEC_ID_H264), NULL) < 0) {
        // Handle error
        avcodec_free_context(&codec_ctx);
        return;
    }

    codec_ctx->thread_count = 4; // Set decoding threads

    // Setup buffer pool for output frames
    AVFrame* frame = av_frame_alloc();
    if (!frame) {
        // Handle error
        avcodec_free_context(&codec_ctx);
        return;
    }

    // Handle codec-specific configurations
    if (config.enable_error_detection) {
        codec_ctx->error_recognition = AV_EF_EXPLODE;
    }

    // Check available buffers
    if (!av_frame_get_buffer(frame, 0)) {
        // Proceed with initialization
        // Notify event handler
        if (event_handler && message_loop) {
            event_handler->on_initialized(context, true);
        }
    } else {
        // Handle buffer allocation failure
        av_frame_free(&frame);
        avcodec_free_context(&codec_ctx);
        if (event_handler && message_loop) {
            event_handler->on_initialized(context, false);
        }
    }
}

