void FFmpegVideoDecodeEngine_Initialize(MessageLoop* message_loop, VideoDecodeEngine::EventHandler* event_handler, VideoDecodeContext* context, const VideoDecoderConfig& config) {
    AVCodecContext* codec_context = avcodec_alloc_context3(NULL);
    if (!codec_context) {
        // Handle allocation failure
        return;
    }

    // Setup codec context based on config
    codec_context->thread_count = 4;  // Example: setting thread count for decoding
    codec_context->flags |= AV_CODEC_FLAG_LOW_DELAY;

    // Set up buffer pool for output frames
    AVBufferPool* buffer_pool = av_buffer_pool_init(codec_context->width, codec_context->height, NULL);
    if (!buffer_pool) {
        avcodec_free_context(&codec_context);
        return;
    }

    // Apply configuration parameters from VideoDecoderConfig
    codec_context->pix_fmt = AV_PIX_FMT_YUV420P;  // Example default format
    codec_context->width = config.width;
    codec_context->height = config.height;

    // Check for available buffers
    AVFrame* frame = av_frame_alloc();
    if (!frame || av_buffer_pool_get(buffer_pool, frame) < 0) {
        av_frame_free(&frame);
        av_buffer_pool_uninit(&buffer_pool);
        avcodec_free_context(&codec_context);
        return;
    }

    // Initialize the codec
    if (avcodec_open2(codec_context, avcodec_find_decoder(AV_CODEC_ID_H264), NULL) < 0) {
        av_frame_free(&frame);
        av_buffer_pool_uninit(&buffer_pool);
        avcodec_free_context(&codec_context);
        return;
    }

    // Notify event handler
    VideoDecodeEngine::Event event;
    event.type = VideoDecodeEngine::Event::Type::kInitialized;
    event_handler->OnEvent(event);

    // Clean up frame and buffer pool
    av_frame_free(&frame);
}

void FFmpegVideoDecodeEngine_Init(MessageLoop* message_loop, VideoDecodeEngine::EventHandler* event_handler, VideoDecodeContext* context, const VideoDecoderConfig& config) {
    AVCodecContext* codec_context = avcodec_alloc_context3(NULL);
    if (!codec_context) {
        // Handle memory allocation failure
        return;
    }

    // Configure codec context based on config parameters
    codec_context->thread_count = 4;  // Standard threading setup for decoding
    codec_context->flags |= AV_CODEC_FLAG_LOW_DELAY;
    codec_context->flags2 |= AV_CODEC_FLAG2_FAST;

    // Setup buffer pool for output frames
    AVBufferPool* buffer_pool = av_buffer_pool_init2(codec_context->width, codec_context->height, codec_context->pix_fmt, NULL, NULL, NULL);
    if (!buffer_pool) {
        // Handle buffer pool initialization failure
        avcodec_free_context(&codec_context);
        return;
    }

    // Additional codec-specific configurations based on the provided config
    if (config.enable_error_detection) {
        codec_context->err_recognition = AV_EF_CRCCheck;
    }

    // Check if codec initialization is successful
    int ret = avcodec_open2(codec_context, avcodec_find_decoder(codec_context->codec_id), NULL);
    if (ret < 0) {
        // Handle codec initialization error
        av_buffer_pool_uninit(&buffer_pool);
        avcodec_free_context(&codec_context);
        return;
    }

    // Notify the event handler of initialization completion
    if (event_handler && event_handler->onInitializationComplete) {
        event_handler->onInitializationComplete(context, true);
    }
}
